// Practice sets that ship with the app. The teacher's Practice sets panel installs one into the database with ais_set_import the first time it is opened to the class,
// so no JSON has to be pasted. (Set 1, Sinag Rice Trading, was imported earlier and lives only in the database.)
// The file is generated by handbook-mfg/ais/set2_tpl.py; the dynamic import keeps its 88 KB out of every page that does not need it.

export type SetDef = { id: string; title: string; topic?: string; summary?: string; txns: unknown[]; meta?: Record<string, unknown> };
export type BuiltinSet = { id: string; load: () => Promise<SetDef> };

export const BUILTIN_SETS: BuiltinSet[] = [
  { id: "pinagpala-expenditure-feb-2027", load: async () => (await import("./aisSets/pinagpala-expenditure-feb-2027.json")).default as unknown as SetDef },
];
